export function CodeSplitting({
  totalSize = {{totalSize}},
  splitMode = "{{splitMode}}",
  accent = "{{accent}}",
  showLabels = {{showLabels}},
}) {
  return (
    <div role="img" aria-label={`${splitMode} bundling of ${totalSize}KB`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 320, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontWeight: 700 }}>{totalSize}KB total &mdash; {splitMode}</p>
      {splitMode === "single"
        ? <div style={{ padding: "14px 10px", borderRadius: 8, background: accent, fontSize: 10, fontWeight: 600 }}>{showLabels && `app.bundle.js \u00B7 ${totalSize}KB \u00B7 loaded before first paint`}</div>
        : (
          <div style={{ display: "flex", gap: 4, height: 30 }}>
            <span style={{ flex: 5, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontSize: 9, fontWeight: 700, overflow: "hidden", background: accent }}>{showLabels && "main"}</span>
            <span style={{ flex: 3, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontSize: 9, fontWeight: 700, overflow: "hidden", background: "#24143030" }}>{showLabels && "/dashboard"}</span>
            <span style={{ flex: 2, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontSize: 9, fontWeight: 700, overflow: "hidden", background: "#24143018" }}>{showLabels && "/settings"}</span>
          </div>
        )}
      <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>
        {splitMode === "single" ? "Everything downloads up front, whether the visitor needs it or not." : <>Only <strong>main</strong> loads first; route chunks load when that route is visited.</>}
      </p>
    </div>
  );
}
